@pytest.mark.parametrize('fixture', ['two-storey', 'three-storey']) @pytest.mark.parametrize('rotated', [False, True]) def test_scaffold_roof_covers_requested_footprint_after_ifc_reopen(tmp_path, fixture, rotated): from text2ifc_agent.complex_scaffold import build_scaffold_candidate from text2ifc_agent.expected_facts import build_expected_facts from text2ifc_compiler import compile_document root = Path(__file__).resolve().parents[2] brief = json.loads((root/f'dataset/processed/agent-demo/phase6.5-cases/{fixture}-case.json').read_text(encoding='utf-8'))['design_brief'] before = copy.deepcopy(brief) expected = build_expected_facts(case_id='roof-bounds', design_brief=brief) value = build_scaffold_candidate(case_id='roof-bounds', design_brief=brief, expected_facts=expected) assert brief == before parent = next(e for e in value['entities'] if e['id']=='building-1')['attributes']['ObjectPlacement'] parent['origin'] = [1300, -700, 500] if rotated: parent['ref_direction'] = [0,1,0] out = tmp_path/'roof.ifc' result = compile_document(value, out) assert result.success, result model = ifcopenshell.open(str(out)) settings = ifcopenshell.geom.settings(); settings.set(settings.USE_WORLD_COORDS, True) shape = ifcopenshell.geom.create_shape(settings, model.by_type('IfcRoof')[0]) vertices = shape.geometry.verts building = brief['known_facts']['building']; roof = expected['roof'] w, d = building['width_x_mm']/1000, building['depth_y_mm']/1000 xy = ([1.3-d,1.3], [-.7,-.7+w]) if rotated else ([1.3,1.3+w], [-.7,-.7+d]) bounds = [*xy, [.5+roof['elevation_mm']/1000, .5+(roof['elevation_mm']+roof['thickness_mm'])/1000]] for axis, interval in enumerate(bounds): > assert [min(vertices[axis::3]), max(vertices[axis::3])] == pytest.approx(interval) E assert [-2.7, 5.3] == approx([1.3 ±....3 ± 9.3e-06]) E E comparison failed. Mismatched elements: 2 / 2: E Max absolute difference: 4.000000000000001 E Max relative difference: 1.4814814814814814 E Index | Obtained | Expected E 0 | -2.7 | 1.3 ± 1.3e-06 E 1 | 5.3 | 9.3 ± 9.3e-06
